import { Box, Stack, TextField, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import { appColors } from '../../../theme/appColors';
import { fieldSx } from '../utils/packageEditor';

interface IPackageIdentityFields {
  packageCode: string;
  packageName: string;
  setPackageCode: React.Dispatch<React.SetStateAction<string>>;
  setPackageName: React.Dispatch<React.SetStateAction<string>>;
  setUnitPrice: React.Dispatch<React.SetStateAction<string>>;
  unitPrice: string;
}

const labelSx = {
  color: alpha('#142352', 0.72),
  fontSize: '0.82rem',
  fontWeight: 700,
  mb: 0.6,
};

const fieldBoxSx = {
  p: 0,
};

const PackageIdentityFields = ({
  packageCode,
  packageName,
  setPackageCode,
  setPackageName,
  setUnitPrice,
  unitPrice,
}: IPackageIdentityFields) => {
  const normalizedUnitPrice = Number(unitPrice || 0);

  return (
  <Box
    sx={{
      background: `linear-gradient(180deg, ${alpha('#E0EAFF', 0.52)} 0%, ${alpha(
        appColors.white,
        0.98
      )} 34%, ${alpha(appColors.white, 0.98)} 100%)`,
      border: '1px solid rgba(96,165,250,0.16)',
      borderRadius: '18px',
      boxShadow: '0 14px 34px rgba(20,35,82,0.06)',
      p: { xs: 2, md: 2.25 },
    }}
  >
    <Stack
      direction={{ xs: 'column', lg: 'row' }}
      justifyContent="space-between"
      spacing={1.5}
      sx={{ mb: 2 }}
    >
      <Box>
        <Typography
          sx={{
            color: '#142352',
            fontSize: '1rem',
            fontWeight: 800,
          }}
        >
          Package details
        </Typography>
        <Typography
          sx={{
            color: alpha('#142352', 0.56),
            fontSize: '0.82rem',
            mt: 0.35,
          }}
        >
          Keep the code, name, and price aligned before updating this package.
        </Typography>
      </Box>

      <Box
        sx={{
          alignSelf: { xs: 'flex-start', lg: 'center' },
          background: alpha('#1D4ED8', 0.08),
          border: '1px solid rgba(37,99,235,0.14)',
          borderRadius: '14px',
          minWidth: { xs: '100%', sm: 220, lg: 240 },
          px: 1.5,
          py: 1.1,
        }}
      >
        <Typography
          sx={{
            color: alpha('#142352', 0.6),
            fontSize: '0.68rem',
            fontWeight: 700,
            letterSpacing: '0.05em',
            textTransform: 'uppercase',
          }}
        >
          Package price
        </Typography>
        <Typography
          sx={{
            color: '#1D4ED8',
            fontSize: '1.15rem',
            fontWeight: 800,
            mt: 0.3,
          }}
        >
          {Number.isFinite(normalizedUnitPrice)
            ? normalizedUnitPrice.toLocaleString('en-US', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
              })
            : '0.00'}
        </Typography>
      </Box>
    </Stack>

    <Box
      sx={{
        display: 'grid',
        gap: 1.5,
        gridTemplateColumns: {
          xs: '1fr',
          md: 'repeat(3, minmax(0, 1fr))',
        },
      }}
    >
      <Box sx={fieldBoxSx}>
        <Typography sx={labelSx}>Package code</Typography>
        <TextField
          fullWidth
          onChange={(event) => setPackageCode(event.target.value)}
          placeholder="Enter package code"
          size="small"
          sx={fieldSx}
          value={packageCode}
        />
      </Box>

      <Box sx={fieldBoxSx}>
        <Typography sx={labelSx}>Package name</Typography>
        <TextField
          fullWidth
          onChange={(event) => setPackageName(event.target.value)}
          placeholder="Enter package name"
          size="small"
          sx={fieldSx}
          value={packageName}
        />
      </Box>

      <Box sx={fieldBoxSx}>
        <Typography sx={labelSx}>Unit price</Typography>
        <TextField
          fullWidth
          inputProps={{ min: 0, step: 'any' }}
          onChange={(event) => setUnitPrice(event.target.value)}
          placeholder="0.00"
          size="small"
          sx={{
            ...fieldSx,
            '& input': {
              fontWeight: 700,
            },
          }}
          type="number"
          value={unitPrice}
        />
      </Box>
    </Box>
  </Box>
  );
};

export default React.memo(PackageIdentityFields);
