import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';

import {
  IPackageDetailsData,
  IPackageSavePayload,
} from '../../../core/Interface/package.interface';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import usePackageEditor from '../hooks/usePackageEditor';
import { dialogPaperSx } from '../utils/packageEditor';
import AvailableProductsPanel from './AvailableProductsPanel';
import PackageIdentityFields from './PackageIdentityFields';
import SelectedProductsPanel from './SelectedProductsPanel';
import WeightedProductDialog from './WeightedProductDialog';

interface IEditPackageModel {
  currencyCode?: string;
  handleCloseDialog: () => void;
  onPackageLoaded?: (packageData: IPackageDetailsData) => void;
  onPackageSaved?: (packageData: IPackageSavePayload) => void;
  open: boolean;
  packageId: string;
}

const EditPackageModel = ({
  currencyCode,
  handleCloseDialog,
  onPackageLoaded,
  onPackageSaved,
  open,
  packageId,
}: IEditPackageModel) => {
  const {
    availableProducts,
    canSave,
    handleCloseWeightedDialog,
    handleConfirmWeightedProduct,
    handleProductCardClick,
    handleQtyChange,
    handleRemoveProduct,
    handleSavePackage,
    isBootstrapping,
    isLoadingProducts,
    isPackageDetailsError,
    isProductError,
    isSavingPackage,
    packageCode,
    packageName,
    productMap,
    searchQuery,
    selectedItems,
    selectedQtyMap,
    setPackageCode,
    setPackageName,
    setSearchQuery,
    setUnitPrice,
    setWeightedQty,
    unitPrice,
    weightedProduct,
    weightedQty,
  } = usePackageEditor({
    handleCloseDialog,
    onPackageLoaded,
    onPackageSaved,
    open,
    packageId,
  });

  return (
    <Dialog
      PaperProps={{ sx: dialogPaperSx }}
      fullWidth
      maxWidth="xl"
      onClose={handleCloseDialog}
      open={open}
      scroll="paper"
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: HEADER_GRADIENT,
            px: { xs: 2.25, md: 3 },
            py: 2.25,
          }}
        >
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '10px',
                display: 'flex',
                flexShrink: 0,
                height: 38,
                justifyContent: 'center',
                width: 38,
              }}
            >
              <Inventory2OutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography
                sx={{
                  color: '#fff',
                  fontSize: '1.05rem',
                  fontWeight: 800,
                  lineHeight: 1.2,
                }}
              >
                Edit Package
              </Typography>
              <Typography
                sx={{
                  color: 'rgba(255,255,255,0.72)',
                  fontSize: '0.78rem',
                  mt: 0.35,
                }}
              >
                Load the package, add products, edit qty, and update it here.
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent
        sx={{
          background: 'linear-gradient(180deg, #F8FAFC 0%, #FDFEFF 100%)',
          display: 'flex',
          flex: 1,
          flexDirection: 'column',
          minHeight: 0,
          overflow: 'hidden',
          p: { xs: 2, md: 3 },
        }}
      >
        {isBootstrapping ? (
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              justifyContent: 'center',
              minHeight: 320,
            }}
          >
            <CircularProgress />
          </Box>
        ) : isPackageDetailsError ? (
          <Box
            sx={{
              alignItems: 'center',
              background: '#F8FAFC',
              border: '1px solid rgba(20,35,82,0.08)',
              borderRadius: '14px',
              boxShadow: '0 1px 4px rgba(20,35,82,0.06)',
              display: 'flex',
              justifyContent: 'center',
              minHeight: 240,
              p: 3,
            }}
          >
            <Typography
              sx={{ color: alpha('#142352', 0.72), fontWeight: 600 }}
            >
              Unable to load package details.
            </Typography>
          </Box>
        ) : (
          <Stack
            spacing={2.5}
            sx={{ flex: 1, minHeight: 0 }}
          >
            <PackageIdentityFields
              packageCode={packageCode}
              packageName={packageName}
              setPackageCode={setPackageCode}
              setPackageName={setPackageName}
              setUnitPrice={setUnitPrice}
              unitPrice={unitPrice}
            />

            <Grid
              alignItems="stretch"
              container
              spacing={2.25}
              sx={{
                flex: 1,
                minHeight: 0,
                '& > .MuiGrid-item': {
                  display: 'flex',
                  minHeight: 0,
                },
              }}
            >
              <Grid
                item
                lg={6}
                sx={{
                  display: 'flex',
                  height: { lg: '100%' },
                  minWidth: 0,
                }}
                xs={12}
              >
                <AvailableProductsPanel
                  availableProducts={availableProducts}
                  currencyCode={currencyCode}
                  handleProductCardClick={handleProductCardClick}
                  isLoadingProducts={isLoadingProducts}
                  isProductError={isProductError}
                  searchQuery={searchQuery}
                  selectedQtyMap={selectedQtyMap}
                  setSearchQuery={setSearchQuery}
                />
              </Grid>

              <Grid
                item
                lg={6}
                sx={{
                  display: 'flex',
                  height: { lg: '100%' },
                  minWidth: 0,
                }}
                xs={12}
              >
                <SelectedProductsPanel
                  currencyCode={currencyCode}
                  handleQtyChange={handleQtyChange}
                  handleRemoveProduct={handleRemoveProduct}
                  productMap={productMap}
                  selectedItems={selectedItems}
                />
              </Grid>
            </Grid>
          </Stack>
        )}
      </DialogContent>

      <DialogActions
        sx={{
          alignItems: { xs: 'stretch', sm: 'center' },
          background: '#FFFFFF',
          borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          justifyContent: 'space-between',
          p: { xs: 2, md: 2.25 },
        }}
      >
        <Typography
          sx={{
            color: alpha('#142352', 0.56),
            display: { xs: 'none', md: 'block' },
            fontSize: '0.78rem',
            fontWeight: 600,
            mr: 2,
          }}
        >
          Review the package details and selected items before saving.
        </Typography>

        <Stack
          direction="row"
          spacing={1.25}
          sx={{ ml: 'auto' }}
        >
          <Button
            onClick={handleCloseDialog}
            sx={{
              borderRadius: '10px',
              fontWeight: 700,
              px: 2,
              textTransform: 'none',
            }}
          >
            Cancel
          </Button>
          <Button
            disabled={!canSave || isSavingPackage || isBootstrapping}
            onClick={handleSavePackage}
            sx={{
              borderRadius: '10px',
              boxShadow: '0 10px 24px rgba(20,30,85,0.22)',
              fontWeight: 800,
              minWidth: 160,
              px: 2.5,
              textTransform: 'none',
            }}
            variant="contained"
          >
            {isSavingPackage ? 'Updating...' : 'Update Package'}
          </Button>
        </Stack>
      </DialogActions>

      <WeightedProductDialog
        currencyCode={currencyCode}
        onAdd={handleConfirmWeightedProduct}
        onChangeQty={setWeightedQty}
        onClose={handleCloseWeightedDialog}
        open={Boolean(weightedProduct)}
        price={weightedProduct?.unitPrice ?? 0}
        productName={weightedProduct?.name ?? ''}
        qty={weightedQty}
      />
    </Dialog>
  );
};

export default React.memo(EditPackageModel);
