import React from 'react';

import {
  IPackageDetailsData,
  IPackageItemData,
  IPackageSavePayload,
} from '../../../core/Interface/package.interface';
import { IProductData } from '../../../core/Interface/product.interface';
import { useNotifier } from '../../../core/Notifier';
import {
  useGetAllProductQuery,
  useGetPackageByIdQuery,
  useSavePackageMutation,
} from '../../posApi';
import {
  defaultProductQuery,
  getNormalizedQty,
  normalizePackageDetails,
  normalizeProductRecords,
} from '../utils/packageEditor';

interface IUsePackageEditor {
  handleCloseDialog: () => void;
  onPackageLoaded?: (packageData: IPackageDetailsData) => void;
  onPackageSaved?: (packageData: IPackageSavePayload) => void;
  open: boolean;
  packageId: string;
}

const usePackageEditor = ({
  handleCloseDialog,
  onPackageLoaded,
  onPackageSaved,
  open,
  packageId,
}: IUsePackageEditor) => {
  const { showErrorMessage, showMessage } = useNotifier();
  const [savePackage, { isLoading: isSavingPackage }] =
    useSavePackageMutation();
  const [searchQuery, setSearchQuery] = React.useState('');
  const [packageCode, setPackageCode] = React.useState('');
  const [packageName, setPackageName] = React.useState('');
  const [unitPrice, setUnitPrice] = React.useState('0');
  const [selectedItems, setSelectedItems] = React.useState<IPackageItemData[]>(
    []
  );
  const [weightedProduct, setWeightedProduct] =
    React.useState<IProductData | null>(null);
  const [weightedQty, setWeightedQty] = React.useState('1');

  const {
    data: packageDetailsResponse,
    isError: isPackageDetailsError,
    isFetching: isFetchingPackageDetails,
    isLoading: isLoadingPackageDetails,
  } = useGetPackageByIdQuery(packageId, {
    refetchOnMountOrArgChange: true,
    skip: !open || !packageId,
  });
  const {
    data: productResponse,
    isError: isProductError,
    isLoading: isLoadingProducts,
  } = useGetAllProductQuery(defaultProductQuery, {
    skip: !open,
  });

  const packageDetails = React.useMemo(
    () => normalizePackageDetails(packageDetailsResponse?.data),
    [packageDetailsResponse?.data]
  );
  const products = React.useMemo(
    () => normalizeProductRecords(productResponse?.data),
    [productResponse?.data]
  );
  const productMap = React.useMemo(
    () =>
      products.reduce<Record<string, IProductData>>((acc, product) => {
        acc[String(product.id)] = product;
        return acc;
      }, {}),
    [products]
  );
  const selectedQtyMap = React.useMemo(
    () =>
      selectedItems.reduce<Record<string, number>>((acc, item) => {
        acc[item.productId] = item.qty;
        return acc;
      }, {}),
    [selectedItems]
  );

  React.useEffect(() => {
    if (!open) {
      return;
    }

    setSearchQuery('');
    setPackageCode('');
    setPackageName('');
    setUnitPrice('0');
    setSelectedItems([]);
    setWeightedProduct(null);
    setWeightedQty('1');
  }, [open, packageId]);

  React.useEffect(() => {
    if (!packageDetails) {
      return;
    }

    setPackageCode(packageDetails.packageCode);
    setPackageName(packageDetails.packageName);
    setUnitPrice(String(packageDetails.unitPrice ?? 0));
    setSelectedItems(packageDetails.items);
    onPackageLoaded?.(packageDetails);
  }, [onPackageLoaded, packageDetails]);

  const normalizedSearchQuery = React.useDeferredValue(
    searchQuery.trim().toLowerCase()
  );

  const availableProducts = React.useMemo(() => {
    const visibleProducts = products.filter(
      (product) => String(product.id) !== packageId
    );

    if (!normalizedSearchQuery) {
      return visibleProducts;
    }

    return visibleProducts.filter((product) =>
      [product.name, product.code, product.categoryName, product.description]
        .join(' ')
        .toLowerCase()
        .includes(normalizedSearchQuery)
    );
  }, [normalizedSearchQuery, packageId, products]);

  const isBootstrapping =
    open &&
    !packageDetails &&
    (isLoadingPackageDetails || isFetchingPackageDetails);

  const canSave =
    packageCode.trim().length > 0 && packageName.trim().length > 0;

  const addProductToPackage = React.useCallback(
    (product: IProductData, qtyToAdd: number) => {
      const normalizedQty = getNormalizedQty(qtyToAdd, product.isKgOrLitre);

      setSelectedItems((currentItems) => {
        const productId = String(product.id);
        const existingItem = currentItems.find(
          (item) => item.productId === productId
        );

        if (!existingItem) {
          return [
            ...currentItems,
            {
              categoryName: product.categoryName,
              isKgOrLitre: product.isKgOrLitre,
              productCode: product.code,
              productId,
              productName: product.name,
              qty: normalizedQty,
              unitPrice: product.unitPrice,
            },
          ];
        }

        return currentItems.map((item) =>
          item.productId === productId
            ? {
                ...item,
                categoryName: item.categoryName || product.categoryName,
                isKgOrLitre:
                  item.isKgOrLitre ?? Boolean(product.isKgOrLitre),
                qty: getNormalizedQty(
                  item.qty + normalizedQty,
                  product.isKgOrLitre
                ),
                unitPrice: item.unitPrice ?? product.unitPrice,
              }
            : item
        );
      });
    },
    []
  );

  const handleProductCardClick = React.useCallback(
    (product: IProductData) => {
      if (product.isKgOrLitre) {
        setWeightedProduct(product);
        setWeightedQty('1');
        return;
      }

      addProductToPackage(product, 1);
    },
    [addProductToPackage]
  );

  const handleRemoveProduct = React.useCallback((productId: string) => {
    setSelectedItems((currentItems) =>
      currentItems.filter((item) => item.productId !== productId)
    );
  }, []);

  const handleQtyChange = React.useCallback(
    (productId: string, nextQty: string, isKgOrLitre?: boolean) => {
      const parsedQty = getNormalizedQty(Number(nextQty || 0), isKgOrLitre);

      setSelectedItems((currentItems) =>
        currentItems.map((item) =>
          item.productId === productId
            ? {
                ...item,
                qty: parsedQty,
              }
            : item
        )
      );
    },
    []
  );

  const handleCloseWeightedDialog = React.useCallback(() => {
    setWeightedProduct(null);
    setWeightedQty('1');
  }, []);

  const handleConfirmWeightedProduct = React.useCallback(() => {
    if (!weightedProduct) {
      return;
    }

    addProductToPackage(weightedProduct, Number(weightedQty || 0));
    handleCloseWeightedDialog();
  }, [
    addProductToPackage,
    handleCloseWeightedDialog,
    weightedProduct,
    weightedQty,
  ]);

  const handleSavePackage = React.useCallback(async () => {
    const payload: IPackageSavePayload = {
      items: selectedItems.map((item) => ({
        productCode: item.productCode,
        productId: item.productId,
        productName: item.productName,
        qty: getNormalizedQty(
          Number(item.qty || 0),
          productMap[item.productId]?.isKgOrLitre ?? item.isKgOrLitre
        ),
      })),
      packageCode: packageCode.trim(),
      packageId,
      packageName: packageName.trim(),
      unitPrice: Number(unitPrice || 0),
    };

    try {
      const response = await savePackage(payload).unwrap();

      if (!response.status) {
        showErrorMessage(response.message);
        return;
      }

      showMessage(response.message);
      onPackageSaved?.(payload);
      handleCloseDialog();
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  }, [
    handleCloseDialog,
    onPackageSaved,
    packageCode,
    packageId,
    packageName,
    productMap,
    savePackage,
    selectedItems,
    showErrorMessage,
    showMessage,
    unitPrice,
  ]);

  return {
    availableProducts,
    canSave,
    handleCloseWeightedDialog,
    handleConfirmWeightedProduct,
    handleProductCardClick,
    handleQtyChange,
    handleRemoveProduct,
    handleSavePackage,
    isBootstrapping,
    isLoadingProducts,
    isPackageDetailsError,
    isProductError,
    isSavingPackage,
    packageCode,
    packageName,
    productMap,
    searchQuery,
    selectedItems,
    selectedQtyMap,
    setPackageCode,
    setPackageName,
    setSearchQuery,
    setUnitPrice,
    setWeightedQty,
    unitPrice,
    weightedProduct,
    weightedQty,
  };
};

export default usePackageEditor;
